@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const modal=new bootstrap.Modal(document.getElementById('serviceOrderModal')),form=document.getElementById('serviceOrderForm'),positions=document.getElementById('orderAnimals'),saved=@json($animalsPayload),cats=@json($categoriesPayload),esc=v=>String(v||'').replaceAll('&','&amp;').replaceAll('"','&quot;'),types=['передержка','выгул','уход'];
function serviceRow(box,index,service={}){let i=box.children.length,row=document.createElement('div');row.className='animal-service-row';row.dataset.type=service.service_type;row.innerHTML=`<strong>${service.service_type||''}</strong><label class="small">Раз в день<input class="form-control" type="number" min="1" max="24" name="animals[${index}][services][${i}][units_per_day]" value="${service.units_per_day||1}"><input type="hidden" name="animals[${index}][services][${i}][service_type]" value="${service.service_type||''}"></label><label class="small">Цена за услугу, ₽<input class="form-control" type="number" min="0" name="animals[${index}][services][${i}][unit_price]" value="${service.unit_price||500}"></label><button type="button" class="btn btn-sm btn-outline-danger" title="Убрать услугу"><i class="fa fa-xmark"></i></button>`;row.querySelector('button').onclick=()=>{row.remove();box.closest('.animal-editor').querySelector(`[data-type="${service.service_type}"]`).classList.remove('is-selected')};box.append(row)}
function animalRow(position={}){let index=positions.children.length,row=document.createElement('section');row.className='animal-editor';let animalOpts='<option value="">Выбрать сохранённого</option>'+saved.map(a=>`<option value="${a.id}" ${String(a.id)===String(position.animal_id)?'selected':''}>${esc(a.name)}${a.client?' · '+esc(a.client):''}</option>`).join(''),catOpts='<option value="">Вид</option>'+cats.map(c=>`<option value="${c.id}" ${String(c.id)===String(position.category_id)?'selected':''}>${esc(c.name)}</option>`).join('');row.innerHTML=`<div class="animal-editor__head"><strong>Питомец</strong><button type="button" class="btn btn-sm btn-outline-danger"><i class="fa fa-trash"></i> Удалить</button></div><div class="animal-editor__fields"><label class="small">Сохранённый<select class="form-select animal-select" name="animals[${index}][animal_id]">${animalOpts}</select></label><label class="small">Или новый<input class="form-control animal-name" name="animals[${index}][name]" value="${esc(position.name)}" placeholder="${esc(position.label||'Кличка')}"></label><label class="small">Вид<select class="form-select animal-category" name="animals[${index}][category_id]">${catOpts}</select></label><label class="small">Количество<input class="form-control" type="number" min="1" name="animals[${index}][quantity]" value="${position.quantity||1}"></label></div><div class="animal-editor__services"><div class="animal-editor__services-title">Услуги для этого питомца</div><div class="animal-service-picker">${types.map(type=>`<button type="button" data-type="${type}">${type[0].toUpperCase()+type.slice(1)}</button>`).join('')}</div><div class="animal-service-list"></div></div>`;row.querySelector('.animal-editor__head button').onclick=()=>row.remove();row.querySelector('.animal-select').onchange=e=>{let a=saved.find(item=>item.id==e.target.value);if(a){row.querySelector('.animal-name').value=a.name;row.querySelector('.animal-category').value=a.category_id||''}};let list=row.querySelector('.animal-service-list');row.querySelectorAll('.animal-service-picker button').forEach(button=>button.onclick=()=>{if(button.classList.contains('is-selected'))return;button.classList.add('is-selected');serviceRow(list,index,{service_type:button.dataset.type,units_per_day:1,unit_price:500})});(position.services||[{service_type:'уход',units_per_day:1,unit_price:500}]).forEach(service=>{row.querySelector(`[data-type="${service.service_type}"]`).classList.add('is-selected');serviceRow(list,index,service)});positions.append(row)}
function open(data){form.action=data?.id?`{{ url('/zooadmin/service-orders') }}/${data.id}`:`{{ route('admin.service-orders.store') }}`;document.getElementById('orderMethod').value=data?.id?'PUT':'POST';document.getElementById('orderModalTitle').textContent=data?.id?'Редактировать заказ':'Новый заказ';document.getElementById('orderClient').value=data?.client_id||'';document.getElementById('orderStart').value=data?.start||'';document.getElementById('orderEnd').value=data?.end||'';document.getElementById('orderAddress').value=data?.address||'';document.getElementById('orderNote').value=data?.note||'';positions.innerHTML='';(data?.animals||[{}]).forEach(animalRow);modal.show()}document.querySelector('.js-new-service-order').onclick=()=>open();document.querySelectorAll('.js-edit-service-order').forEach(button=>button.onclick=()=>open(JSON.parse(button.dataset.order)));document.getElementById('addOrderAnimal').onclick=()=>animalRow();});
</script>@endpush
@endsection
